const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  page.on('console', msg => { if (msg.type() === 'error') console.log('CONSOLE ERROR:', msg.text()); });

  await page.goto('http://localhost:8791/index.html');
  await page.waitForSelector('text=Kick Off');

  // Select Ultra Mode format
  await page.click('button:has-text("Ultra Mode")');
  await page.waitForTimeout(200);

  await page.click('.fd-kick');
  await page.waitForTimeout(500);

  // Draft 11 players
  for (let i = 0; i < 11; i++) {
    await page.waitForSelector('.fd-cand.elig', { timeout: 15000 });
    await page.waitForTimeout(150);
    await page.click('.fd-cand.elig >> nth=0');
    await page.waitForSelector('.fd-slot.hl', { timeout: 15000 });
    await page.click('.fd-slot.hl >> nth=0');
    await page.waitForTimeout(250);
  }

  await page.waitForSelector('text=Run the simulation', { timeout: 15000 });
  console.log('DRAFT COMPLETE, moving to teamsheet');
  await page.screenshot({ path: '/tmp/pwtest/01_teamsheet.png' });

  await page.click('button:has-text("Run the simulation")');
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/pwtest/02_result_start.png' });

  // Check the mode badge shows Ultra
  const badgeText = await page.textContent('.fd-modebadges');
  console.log('MODE BADGE:', badgeText);

  // Drive through the whole run: skip games, click continue/proceed buttons, handle shootout by auto-picking
  let iterations = 0;
  let leaguePhaseCount = null;
  while (iterations < 400) {
    iterations++;
    // Check the running h3 title + league phase match count right before it clears
    const runH = await page.$('.fd-run-h');
    if (runH) {
      const t = await runH.textContent();
      if (t === 'League phase') {
        const rows = await page.$$('.fd-matchrow');
        leaguePhaseCount = rows.length;
      }
    }

    if (await page.$('button:has-text("Skip game")')) {
      await page.click('button:has-text("Skip game")');
      await page.waitForTimeout(80);
      continue;
    }
    if (await page.$('button:has-text("Continue")')) {
      await page.click('button:has-text("Continue")');
      await page.waitForTimeout(200);
      continue;
    }
    if (await page.$('button:has-text("Proceed to")')) {
      await page.click('button:has-text("Proceed to")');
      await page.waitForTimeout(300);
      continue;
    }
    if (await page.$('button:has-text("See the result")')) {
      await page.click('button:has-text("See the result")');
      await page.waitForTimeout(300);
      continue;
    }
    if (await page.$('button:has-text("See the standings")')) {
      await page.click('button:has-text("See the standings")');
      await page.waitForTimeout(300);
      continue;
    }
    if (await page.$('button:has-text("View the bracket")')) {
      await page.click('button:has-text("View the bracket")');
      await page.waitForTimeout(300);
      continue;
    }
    if (await page.$('button:has-text("Play the")')) {
      await page.click('button:has-text("Play the")');
      await page.waitForTimeout(300);
      continue;
    }
    if (await page.$('button:has-text("To penalties")')) {
      await page.click('button:has-text("To penalties")');
      await page.waitForTimeout(300);
      continue;
    }
    // Shootout: pick a shot zone if present
    const pkZone = await page.$('.fd-pk-zone.live');
    if (pkZone) {
      await pkZone.click();
      await page.waitForTimeout(400);
      continue;
    }
    // Final verdict reached?
    if (await page.$('text=Final Verdict')) {
      console.log('REACHED FINAL VERDICT after', iterations, 'loop iterations');
      break;
    }
    await page.waitForTimeout(150);
  }

  console.log('LEAGUE PHASE MATCH COUNT SEEN:', leaguePhaseCount);

  await page.screenshot({ path: '/tmp/pwtest/03_final.png', fullPage: true });

  const finalText = await page.textContent('.fd-verdict.summary, .fd-verdict.rise.summary').catch(() => null);
  console.log('FINAL VERDICT BLOCK:', finalText);

  const kick = await page.textContent('.kick').catch(() => null);
  console.log('KICK LINE (Final Verdict header):', kick);

  const recordPills = await page.$$eval('.fd-record-pills .fd-rp', els => els.map(e => e.textContent));
  console.log('RECORD PILLS:', recordPills);

  await browser.close();
})();
